\foreach \x [evaluate=\x as \y using f(\x)] in {6.5,7.0,...,9}{
	\edef\temp{
		\noexpand
		\node[circle, draw=none, fill=deepskyblue, inner sep=1.5pt] at (axis cs: \x, \y+rand*\spread) {};
	}\temp
} 

\draw[->, fadedpink, thick, shorten <          = 1.5mm, shorten >= 1.5mm] (axis cs:7,-4) -- (axis cs:7,-2) node[circle, inner sep=2pt, draw=none, fill=red] {};

\draw[->, fadedpink, thick, shorten <          = 1.5mm, shorten >= 1.5mm] (axis cs:6,6) -- (axis cs:6,4) node[circle, inner sep=2pt, draw=none, fill=red] {};

\end{axis}

\end{tikzpicture}
